  "data": {
    "content": "// Package factsoutbox builds the repofacts.v1.FactSet payloads the cell pushes to
// entire-core's RecordFacts RPC (COR-991), and owns the outbox's shard math. It is
// the ONLY entire-api package that imports the entiredb repofacts module directly:
// the store's enqueue and the facts relay both go through here, so the fact
// registry, the wire-arm/WireType invariant, and the "source = github" provenance
// live in one testable place.
//
// A FactSet is one observation of one emitter group at one observed_at. This slice
// builds the directly-observed groups: META (stars, forks, language, private,
// archived) from github_meta; ACTIVITY (checkpoint_count,
// last_activity_at, activity_hotness) from checkpoints; PUSH (last_pushed_at)
// from object-ref events; and PRS (open_pr_count) from the PR projection.
// Meta is ungated (source "github"). Entire-derived groups use source "entire";
// their projection transactions gate emission to the processing primary. Core
// collapses duplicates per group last-writer-wins on <group>_observed_at.
// repo_id on every set is the PLACEMENT repo ULID; core resolves it to the repo group.
package factsoutbox

import (
	"fmt"
	"hash/fnv"
	"time"

	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/types/known/timestamppb"

	"github.com/entirehq/entiredb/modules/repofacts"
	repofactsv1 "github.com/entirehq/entiredb/modules/repofacts/gen/repofacts/v1"
)

// Source is the provenance stamped on the META FactSet: the value came from GitHub
// (via the mirror-pipeline meta webhook), so core records it as github-observed.
const Source = "github"

// SourceEntire is the provenance stamped on the ACTIVITY and PRS FactSets: those
// facts are Entire-derived (aggregated from this cell's own checkpoint / PR
// projections), not read from an upstream forge, so their provenance is "entire".
const SourceEntire = "entire"

// GroupMeta is the meta emitter group as the wire/outbox string. It is the outbox
// row's fact_group and the coalescing key's second column.
const GroupMeta = string(repofacts.GroupMeta)

// GroupActivity, GroupPush, and GroupPRs are the Entire-derived emitter groups
// as their outbox fact_group strings. Each coalesces independently (one outbox row
// per repo) and carries its own <group>_observed_at / <group>_source at core.
const (
	GroupActivity = string(repofacts.GroupActivity)
	GroupPush     = string(repofacts.GroupPush)
	GroupPRs      = string(repofacts.GroupPRs)
)

// NumShards partitions repo_facts_outbox so worker replicas drain different shards
// concurrently. FIXED (a row's shard is hash%N): changing N would orphan in-flight
// rows. Fact apply is idempotent + commutative (LWW), so shard ordering is not a
// correctness requirement — the shard only spreads drain work. Mirrors
// reposettings.NumShards / facetOutboxShards.
const NumShards = 64

// ShardFor maps a placement repo ULID to its outbox shard — stable for the repo's
// lifetime, so all of a repo's observations drain on one shard. fnv32a % N, matching
// reposettings.ShardFor / facetShardFor.
func ShardFor(repoID string) int16 {
	h := fnv.New32a()
	_, _ = h.Write([]byte(repoID))
	return int16(h.Sum32() % NumShards) //nolint:gosec // 0..NumShards-1
}

// MetaObservation is one github_meta observation, as the meta-group facts it
// carries. Pointer fields are absent-vs-observed: nil Private/Archived is "not
// observed" and is left out of the set entirely, so it never overwrites a value
// core already holds; a zero Stars/Forks is a real observation (the event always
// carries them) and is always emitted.
type MetaObservation struct {
	Stars      int
	Forks      int
	Language   string
	Private    *bool
	Archived   *bool
	ObservedAt time.Time
}

// BuildMetaSet builds the meta FactSet for the placement repo. The fact names and
// value arms are fixed literals matching repofacts.Registry (meta group); that this
// emitter and the registry core routes on can't drift is asserted once by a unit
// test, not re-checked per event on this high-rate path. Absent optional fields
// (empty language, nil private/archived) are omitted so a partial
// observation never clobbers a value core already holds; stars and forks are always
// present.
func BuildMetaSet(repoID string, obs MetaObservation) *repofactsv1.FactSet {
	facts := make([]*repofactsv1.Fact, 0, 5)
	facts = append(facts,
		&repofactsv1.Fact{Name: "stars", Value: &repofactsv1.Fact_IntValue{IntValue: int64(obs.Stars)}},
		&repofactsv1.Fact{Name: "forks", Value: &repofactsv1.Fact_IntValue{IntValue: int64(obs.Forks)}},
	)
	if obs.Language != "" {
		facts = append(facts, &repofactsv1.Fact{Name: "language", Value: &repofactsv1.Fact_StringValue{StringValue: obs.Language}})
	}
	if obs.Private != nil {
		facts = append(facts, &repofactsv1.Fact{Name: "private", Value: &repofactsv1.Fact_BoolValue{BoolValue: *obs.Private}})
	}
	if obs.Archived != nil {
		facts = append(facts, &repofactsv1.Fact{Name: "archived", Value: &repofactsv1.Fact_BoolValue{BoolValue: *obs.Archived}})
	}
	return &repofactsv1.FactSet{
		RepoId:     repoID,
		Source:     Source,
		ObservedAt: timestamppb.New(obs.ObservedAt),
		Facts:      facts,
	}
}

// MarshalMetaSet builds a meta FactSet and returns its wire bytes for the outbox
// payload. The relay round-trips these bytes through Unmarshal.
func MarshalMetaSet(repoID string, obs MetaObservation) ([]byte, error) {
	b, err := proto.Marshal(BuildMetaSet(repoID, obs))
	if err != nil {
		return nil, fmt.Errorf("factsoutbox: marshal %s: %w", repoID, err)
	}
	return b, nil
}

// ActivityObservation is one observation of a repo's Entire-derived activity, as
// the activity-group facts it carries. CheckpointCount is an AGGREGATE (the repo's
// current checkpoint total) and is always emitted, so a genuine zero is recorded.
// LastActivityAt and Hotness are absent-vs-observed: a nil pointer is left out of the
// set so it never overwrites a value core already holds; a set value is emitted.
// LastActivityAt is",
