// configuration. A bad config must fail loudly at startup, before the process
// binds a port, so misconfiguration never reaches production half-running.
package config

import (
	"errors"
	"fmt"
	"net/http"
	"net/url"
	"os"
	"path"
	"strconv"
	"strings"
	"time"
)

// Upstream is one configured backend whose OpenAPI spec the gateway aggregates
// and whose requests it proxies.
//
// SpecURL is fetched (and may auto-resolve through an HTML docs page). BaseURL
// is the trusted proxy destination — derived from SpecURL's directory unless an
// explicit override is given. The spec's own servers[] is intentionally NOT
// used for routing: trusting network-fetched content to decide
// where bearer tokens go is a token-exfiltration vector.
type Upstream struct {
	Name    string
	SpecURL *url.URL
	BaseURL *url.URL

	// Local, when non-nil, marks an in-process upstream: the gateway serves its
	// requests with this handler instead of reverse-proxying over HTTP, and its
	// spec is provided directly as LocalSpec rather than fetched from SpecURL
	// (which is nil for a local upstream). This is how entire-api carries its own
	// activity surface in the same process: the merged document and routing table
	// treat it like any other upstream, but no network hop or spec fetch occurs.
	//
	// LocalPrefix is re-prepended to the request path before the handler sees it.
	// The proxy router runs after the gateway base path is stripped, so a local
	// upstream's paths arrive bare (e.g. /me); LocalPrefix restores the in-process
	// mux's own mount (e.g. /api/v1), the in-process analogue of an HTTP upstream's
	// BaseURL path join.
	Local       http.Handler
	LocalPrefix string
	LocalSpec   []byte
	// RouteOnlyPaths are in-process operation patterns that must be routable but
	// intentionally absent from the merged public OpenAPI document (for example,
	// service-authenticated ingestion endpoints). They are never accepted for a
	// remote upstream: route-only remote destinations would evade the reviewed
	// spec and could receive bearer tokens without an advertised operation.
	RouteOnlyPaths []string

	// PathPrefix sub-paths a (remote) upstream's whole surface under one segment
	// in the merged document, keeping it disjoint from another upstream that owns
	// the bare namespace. The merge prepends it to every path key (so entiredb's
	// /repos/... is published as /git/repos/...) and the proxy strips it back off
	// before joining BaseURL, since the backend still serves the bare path. It is
	// the mirror of LocalPrefix: LocalPrefix prepends in-process because the local
	// mux expects its own mount; PathPrefix strips on the way out because BaseURL
	// already implies the upstream's real prefix. Empty = published bare.
	PathPrefix string

	// AllowedMethods has three states. nil (the default) means "any method" —
	// preserved for every upstream that never triggers the restriction. A
	// non-nil, non-empty slice restricts the path to exactly these HTTP
	// methods (uppercase); any other method on the same pattern gets a 405,
	// never the upstream. A non-nil, EMPTY slice denies every method: the
	// path's only operation(s) were dropped entirely. Set per-path by
	// merge.mergePaths when it drops a mutualTLS-only operation (see
	// isMTLSOnlySecurity) — see proxy.BuildRouter for how each state is
	// enforced.
	AllowedMethods []string

	// Required marks a load-bearing upstream: cell readiness (Store.AllReady)
	// gates only on required upstreams committing a spec. A DOWN optional upstream
	// (peregrine/search) degrades its own routes but must NOT hold the pod
	// out of rotation — entire-api is load-bearing and stays Ready serving the rest
	// of the surface. Set from the service template's Required flag (topology.go);
	// a local in-process upstream is always required (it's the product surface,
	// always available). Default false: an unmarked upstream is optional.
	Required bool
}

// NewLocalUpstream builds an in-process upstream: its spec bytes are provided
// directly (rendered from the in-process OpenAPI surface, not fetched) and its
// requests are served by handler with prefix re-prepended to the base-stripped
// path. SpecURL/BaseURL stay nil — a local upstream is never fetched or proxied.
func NewLocalUpstream(name, prefix string, handler http.Handler, spec []byte) Upstream {
	// Required: the in-process product surface is always required (see Upstream.Required).
	return Upstream{Name: name, Local: handler, LocalPrefix: prefix, LocalSpec: spec, Required: true}
}

// Config is the fully-parsed, validated runtime configuration.
type Config struct {
	Environment  Environment
	Jurisdiction Jurisdiction
	Region       string
	Cell         str",
